window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-12591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκνήφω</h1><div class=\"entry-meta\"><span>DGP · ordem 1352 na letra ε · nº geral 12591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer passar a bebedeira; curar a bebedeira; tornar-se sóbrio de novo 2 recuperar-se 3 arrepender-se.</p></section></article>\n<article id=\"entry-dgp-12592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκνήχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1353 na letra ε · nº geral 12592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκνέω.</p></section></article>\n<article id=\"entry-dgp-12593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκνίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1354 na letra ε · nº geral 12593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκνίπτω.</p></section></article>\n<article id=\"entry-dgp-12594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκνικάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1355 na letra ε · nº geral 12594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vencer; triunfar de; prevalecer sobre algo ou alguém, ac. 2 conseguir finalmente que, inf. 3 (opinião) ser vencedor; prevalecer: ἐκν. ἅπασι tuc. prevalecer entre todos 4 fazer prevalecer uma opinião de que, or. inf.</p></section></article>\n<article id=\"entry-dgp-12595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκνίπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1356 na letra ε · nº geral 12595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκνίψω) 1 lavar (coisas); lavar (uma mancha) 2 purgar; expiar 3 lavar bem; limpar; purificar ♦ méd. 4 lavar-se; purificar-se.</p></section></article>\n<article id=\"entry-dgp-12596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκνόμιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1357 na letra ε · nº geral 12596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">enorme; extraordinário. 〈ἐκ, νόμος〉</p></section></article>\n<article id=\"entry-dgp-12597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκνομίως</h1><div class=\"entry-meta\"><span>DGP · ordem 1358 na letra ε · nº geral 12597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. extraordinariamente.</p></section></article>\n<article id=\"entry-dgp-12598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκνομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1359 na letra ε · nº geral 12598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 contrário à lei; fora da lei; ilegal 2 contrário ao costume; irregular; extraordinário 3 monstruoso. 〈ἐκ, νόμος〉</p></section></article>\n<article id=\"entry-dgp-12599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκνόμως</h1><div class=\"entry-meta\"><span>DGP · ordem 1360 na letra ε · nº geral 12599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo horrível; de maneira monstruosa.</p></section></article>\n<article id=\"entry-dgp-12600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκνοος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 1361 na letra ε · nº geral 12600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">privado de juízo; insensato. 〈ἐκ, νόος〉</p></section></article>\n<article id=\"entry-dgp-12601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκνοστέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1362 na letra ε · nº geral 12601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. aor.) retornar; voltar.</p></section></article>\n<article id=\"entry-dgp-12602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκόμισσα</h1><div class=\"entry-meta\"><span>DGP · ordem 1363 na letra ε · nº geral 12602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ép. de κομίζω.</p></section></article>\n<article id=\"entry-dgp-12603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκοντί</h1><div class=\"entry-meta\"><span>DGP · ordem 1364 na letra ε · nº geral 12603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de bom grado; voluntariamente. 〈ἑκών〉</p></section></article>\n<article id=\"entry-dgp-12604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκόπην</h1><div class=\"entry-meta\"><span>DGP · ordem 1365 na letra ε · nº geral 12604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κόπτω.</p></section></article>\n<article id=\"entry-dgp-12605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκούσιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1366 na letra ε · nº geral 12605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 voluntário; feito voluntariamente 2 que age voluntariamente (pessoa); de bom grado; ἑκουσίᾳ, ἐξ ἑκουσίας, καθ᾽ ἑκουσίαν voluntariamente ♦ ἑκούσιον adv. 3 voluntariamente ♦ τὰ ἑκούσια 4 os atos voluntários.</p></section></article>\n<article id=\"entry-dgp-12606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκουσίως</h1><div class=\"entry-meta\"><span>DGP · ordem 1367 na letra ε · nº geral 12606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. voluntariamente.</p></section></article>\n<article id=\"entry-dgp-12607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπαγλέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1368 na letra ε · nº geral 12607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar estupefato de que, or. conj. (ὡς) 2 olhar com admiração; admirar-se de, ac. 〈ἔκπαγλος〉</p></section></article>\n<article id=\"entry-dgp-12608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπαγλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1369 na letra ε · nº geral 12608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espantoso; terrível; violento 2 admirável; extraordinário ♦ ἔκπαγλον e ἔκπαγλα 3 terrivelmente 4 maravilhosamente. 〈ἐκπλήσσω〉</p></section></article>\n<article id=\"entry-dgp-12609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπάγλως</h1><div class=\"entry-meta\"><span>DGP · ordem 1370 na letra ε · nº geral 12609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. terrivelmente.</p></section></article>\n<article id=\"entry-dgp-12610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπαιδεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1371 na letra ε · nº geral 12610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 criar desde a infância; educar; formar 2 ensinar algo, ac., a alguém, ac. ou dat.</p></section></article>\n<article id=\"entry-dgp-12611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπαιφάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1372 na letra ε · nº geral 12611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) manifestar-se com fúria; entregar-se à fúria.</p></section></article>\n<article id=\"entry-dgp-12612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπαίω</h1><div class=\"entry-meta\"><span>DGP · ordem 1373 na letra ε · nº geral 12612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπαιήσω, aor. ἐξέπαισα) 1 fazer cair; derrubar alguém, ac., de, gen. ♦ intr. e méd. 2 cair fora; escapar.</p></section></article>\n<article id=\"entry-dgp-12613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπαλαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1374 na letra ε · nº geral 12613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. há muito tempo.</p></section></article>\n<article id=\"entry-dgp-12614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπάλλομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1375 na letra ε · nº geral 12614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª sing. aor.2 poét. ἔκπαλτο) jorrar de; lançar-se de, gen.</p></section></article>\n<article id=\"entry-dgp-12615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπατάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1376 na letra ε · nº geral 12615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acabrunhar; abater ♦ pas. 2 estar abatido: φρένας ἐκπεπαγμένος hom. de ânimo acabrunhado.</p></section></article>\n<article id=\"entry-dgp-12616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπάτιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1377 na letra ε · nº geral 12616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que sai do ordinário; extraordinário; enorme. 〈ἐκ, πατέω2〉</p></section></article>\n<article id=\"entry-dgp-12617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπαύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1378 na letra ε · nº geral 12617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer cessar ♦ méd. 2 cessar; parar; repousar.</p></section></article>\n<article id=\"entry-dgp-12618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπείθω</h1><div class=\"entry-meta\"><span>DGP · ordem 1379 na letra ε · nº geral 12618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">persuadir completamente.</p></section></article>\n<article id=\"entry-dgp-12619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπειράζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1380 na letra ε · nº geral 12619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. colocar à prova; testar.</p></section></article>\n<article id=\"entry-dgp-12620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπειράομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1381 na letra ε · nº geral 12620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπειράσομαι, aor. ἐξεπειράθην) 1 testar; provar alguém, gen. 2 tentar algo, inf. 3 procurar saber algo, ac., de alguém, gen. 4 perguntar se, or. conj. (εἰ).</p></section></article>\n<article id=\"entry-dgp-12621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπέλει é</h1><div class=\"entry-meta\"><span>DGP · ordem 1382 na letra ε · nº geral 12621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">permitido. 〈ἐκ, πέλω〉</p></section></article>\n<article id=\"entry-dgp-12622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεμπτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1383 na letra ε · nº geral 12622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἐκπέμπω.</p></section></article>\n<article id=\"entry-dgp-12623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπέμπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1384 na letra ε · nº geral 12623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπέμψω etc.) 1 enviar; fazer ir; despachar alguém, ac., para longe ou para fora de, gen. ou ἐκ e gen. 2 enviar; despedir; repudiar uma mulher 3 fazer partir; fazer sair; enviar (embaixadores, expedições, colonos) 4 enviar algo, ac., a alguém, dat. 5 exportar (mercadorias) 6 exalar sopro, odor 7 espalhar luz ♦ méd. 8 fazer vir para fora; chamar para fora de, gen. 9 expulsar ♦ pas. 10 afastar-se; partir 11 morrer.</p></section></article>\n<article id=\"entry-dgp-12624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπεμψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1385 na letra ε · nº geral 12624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">envio. 〈ἐκπέμπω〉</p></section></article>\n<article id=\"entry-dgp-12625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεπέτασμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1386 na letra ε · nº geral 12625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de ἐκπετάννυμι.</p></section></article>\n<article id=\"entry-dgp-12626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπέποται</h1><div class=\"entry-meta\"><span>DGP · ordem 1387 na letra ε · nº geral 12626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. perf. pas. de ἐκπίνω.</p></section></article>\n<article id=\"entry-dgp-12627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπέπραται</h1><div class=\"entry-meta\"><span>DGP · ordem 1388 na letra ε · nº geral 12627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐκπιπράσκω.</p></section></article>\n<article id=\"entry-dgp-12628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεπταμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 1389 na letra ε · nº geral 12628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. expansivamente. 〈ἐκπετάννυμι〉</p></section></article>\n<article id=\"entry-dgp-12629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεράᾳ</h1><div class=\"entry-meta\"><span>DGP · ordem 1390 na letra ε · nº geral 12629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. pres. ind. ép. de ἐκπεράω.</p></section></article>\n<article id=\"entry-dgp-12630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1391 na letra ε · nº geral 12630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 levar a seu termo; terminar; findar ♦ méd. pas. 2 (oráculo) cumprir-se.</p></section></article>\n<article id=\"entry-dgp-12631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπέραμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1392 na letra ε · nº geral 12631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">saída. 〈ἐκπεράω〉</p></section></article>\n<article id=\"entry-dgp-12632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1393 na letra ε · nº geral 12632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 passar para o outro lado; transpor; atravessar 2 passar (a vida, infortúnio) 3 (dardo) atingir 4 chegar a um lugar, ac. 5 sair de, gen. 6 bíbl. transportar.</p></section></article>\n<article id=\"entry-dgp-12633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπέρθω</h1><div class=\"entry-meta\"><span>DGP · ordem 1394 na letra ε · nº geral 12633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπέρσω) 1 destruir totalmente; devastar cidades; derrubar a tirania de Zeus 2 pilhar; saquear.</p></section></article>\n<article id=\"entry-dgp-12634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπερίειμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1395 na letra ε · nº geral 12634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. ἐκπεριϊέναι) aproximar-se rodeando; contornar.</p></section></article>\n<article id=\"entry-dgp-12635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεριέρχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1396 na letra ε · nº geral 12635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκπερίειμι.</p></section></article>\n<article id=\"entry-dgp-12636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεριϊέναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1397 na letra ε · nº geral 12636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκπερίειμι.</p></section></article>\n<article id=\"entry-dgp-12637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεριοδεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1398 na letra ε · nº geral 12637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar a volta completa em, ac. 2 examinar por todos os lados 3 envolver completamente (mulheres, paixões).</p></section></article>\n<article id=\"entry-dgp-12638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεριπλέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1399 na letra ε · nº geral 12638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">circunavegar.</p></section></article>\n<article id=\"entry-dgp-12639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπερισσῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1400 na letra ε · nº geral 12639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., bíbl. de maneira completamente excessiva. 〈ἐκ, περισσός〉</p></section></article>\n<article id=\"entry-dgp-12640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπερόωσι</h1><div class=\"entry-meta\"><span>DGP · ordem 1401 na letra ε · nº geral 12640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. pres. ind. ép. de ἐκπεράω.</p></section></article>\n<article id=\"entry-dgp-12641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπέρυσι</h1><div class=\"entry-meta\"><span>DGP · ordem 1402 na letra ε · nº geral 12641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. há mais de um ano.</p></section></article>\n<article id=\"entry-dgp-12642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπεσε</h1><div class=\"entry-meta\"><span>DGP · ordem 1403 na letra ε · nº geral 12642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 ép., ἐκπεσέειν inf. aor.2 jôn., ἔκπεσον 3ª pl. aor.2 ép., de ἐκπίπτω.</p></section></article>\n<article id=\"entry-dgp-12643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπετάννυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1404 na letra ε · nº geral 12643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπετάσω, aor. ἐξεπέτασα, perf. desus.; pas. aor. ἐξεπετάσθην, perf. ἐξεπεπέτασμαι) 1 desdobrar; estender ♦ méd. pas. 2 desdobrar-se; estender-se 3 perf. ser desdobrado; ser estendido.</p></section></article>\n<article id=\"entry-dgp-12644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπέτασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1405 na letra ε · nº geral 12644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desdobramento; expansão. 〈ἐκπε­τάννυμι〉</p></section></article>\n<article id=\"entry-dgp-12645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπετάσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1406 na letra ε · nº geral 12645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de ἐκπετάννυμι.</p></section></article>\n<article id=\"entry-dgp-12646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπετήσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1407 na letra ε · nº geral 12646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">apto ou pronto para voar. 〈ἐξίπταμαι〉</p></section></article>\n<article id=\"entry-dgp-12647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεύθομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1408 na letra ε · nº geral 12647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκπυνθάνομαι.</p></section></article>\n<article id=\"entry-dgp-12648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπεφυυῖαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1409 na letra ε · nº geral 12648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. ép. fem. pl. de ἐκφύομαι.</p></section></article>\n<article id=\"entry-dgp-12649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπήγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1410 na letra ε · nº geral 12649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπήξω, aor. ἐξέπηξα; pas. aor.2 ἐξεπάγην) 1 tornar espesso, pesado 2 condensar; congelar ♦ pas. 3 condensar-se; congelar-se.</p></section></article>\n<article id=\"entry-dgp-12650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπηγνύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1411 na letra ε · nº geral 12650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκπήγνυμι.</p></section></article>\n<article id=\"entry-dgp-12651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπηδάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1412 na letra ε · nº geral 12651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 saltar para, εἰς e ac., contra, ἐπί e ac. 2 sair do leito 3 sair; escapar de, ἐκ e gen. 4 sair do lugar; (articulação) deslocar-se.</p></section></article>\n<article id=\"entry-dgp-12652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπηδέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1413 na letra ε · nº geral 12652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐκπηδάω.</p></section></article>\n<article id=\"entry-dgp-12653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπήδημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1414 na letra ε · nº geral 12653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">salto; ímpeto. 〈ἐκπηδάω〉</p></section></article>\n<article id=\"entry-dgp-12654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπιδύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1415 na letra ε · nº geral 12654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">surdir; jorrar.</p></section></article>\n<article id=\"entry-dgp-12655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπιέζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1416 na letra ε · nº geral 12655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prensar; espremer 2 repelir à força 3 oprimir.</p></section></article>\n<article id=\"entry-dgp-12656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπιεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1417 na letra ε · nº geral 12656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 poét. de ἐκπίνω.</p></section></article>\n<article id=\"entry-dgp-12657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπίμπλημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1418 na letra ε · nº geral 12657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπλήσω, aor. ἐξέπλησα etc.) 1 encher algo 2 tornar farto; saciar; satisfazer (desejos) 3 tornar completo; completar 4 levar a termo; cumprir (destino, prescrições); acabar (ano, vida) 5 acabar de, part. 6 acabar de contar, de expor.</p></section></article>\n<article id=\"entry-dgp-12658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1419 na letra ε · nº geral 12658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπίομαι, aor.2 ἐξέπιον; pas. fut. ἐκποθήσομαι, aor. ἐξεπόθην, perf. ἐκπέπομαι) 1 beber 2 esvaziar 3 con­sumir; exaurir.</p></section></article>\n<article id=\"entry-dgp-12659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπιον</h1><div class=\"entry-meta\"><span>DGP · ordem 1420 na letra ε · nº geral 12659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor.2 poét. de ἐκπίνω.</p></section></article>\n<article id=\"entry-dgp-12660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπιπράσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1421 na letra ε · nº geral 12660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(perf. pas. 3ª sing. ἐκπέπραται) vender.</p></section></article>\n<article id=\"entry-dgp-12661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπίπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1422 na letra ε · nº geral 12661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκπεσοῦμαι, aor.2 ἐξέπεσον, perf. ἐκπέπτωκα, m.-q.-perf. ἐξεπεπτώκειν) 1 cair de, gen. ou ἀπό e gen. 2 ser expulso; ser exilado; ser banido de, gen. ou ἐκ e gen., por alguém, ὑπό ou πρός e gen. 3 ser derrubado; ser desapossado de, gen. 4 cair; despencar; decair; fracassar; falhar 5 (carne putrefata, dentes, penas) soltar-se e cair; (articulações) deslocar-se; luxar 6 desviar-se; afastar-se de, gen. ou ἐκ e gen. 7 ir dar em (por ter-se afastado); encalhar, πρός ou εἰς e ac., πρός e dat. 8 mudar; degenerar 9 precipitar-se fora de; sair precipitadamente de, gen. ou ἐκ e gen. 10 sair de; fugir, ἐκ e gen. 11 cair no domínio público; ser divulgado; espalhar-se 1 σκῆπτρον δὲ οἱ ἔκπεσε χειρός hom. o cetro caiu-lhe da mão, εὐεργέος ἔκπεσε δίφρου hom. caiu do carro bem fabricado, ἐκπ. ἀντύγων ἄπο eur. cair do carro, οἱ λεγόμενοι ἀστέρες ἐκπίπτειν ep. os astros dos quais se diz que caem, i. e., os meteoros 2 ἐκπίπτειν ἐκ Πελοποννήσου ὑπὸ Μήδων her. ser expulso do Peloponeso pelos medas, ἐκ πολλῶν τε καὶ εὐδαιμόνων ἐκπεσών her. tendo perdido uma situação em que tinha riqueza e felicidade, οὐ γὰρ δὴ ἑτέρων ἔργων αἰτίαν λαβόντες ἐκ τῆς πόλεως ἐξέπεσον, ἀλλὰ τούτων lís. pois não é sob uma outra acusação que eles foram exilados da cidade, mas por isso 3 πρὸς ὧν ἐκπίπτει κράτους ésql. pelos quais é derrubado do poder, ἵνα τῶν ἐλπίδων ἐκπίπτοιεν tuc. a fim de que perdessem as esperanças 4 οἱ Πέρσαι ἐκπίπτουσι τῇσι νηυσὶ ἐς Ἰηπυγίην her. os persas caem com suas naus na Iapígia, ἔσφαξεν αὑτὸν καὶ ἐξέπεσεν ἐς τὸν Ναυπακτίων λιμένα tuc. ele degolou a si mesmo e caiu no porto de Naupacto 5 φύσιες φυσίων μέγα διαφέρουσιν ἐς τὸ ῥηϊδίως ἐμπίπ­τειν τὰ ἐκπίπτοντα hipócr. as compleições são muito diferentes umas das outras no tocante à facilidade de redução das luxações 6 ἐκπ. ἐκ τἦς ὁδοῦ xen. afastar-se da estrada, ἐκπ. ἐκ τοῦ λόγου ésql. afastar-se do tema do discurso, εἰ ἐκπέσοιμι τῶν ἐμαυτοῦ λογισμῶν plut. se abandonasse meus desígnios 7 ἐκπ. πρὸς πέτραις eur. ir dar nos rochedos, ἐκπ. ἐς τὸν λιμένα tuc. ir dar no porto, ἐκπ. πρὸς τὴν χῶραν plat. ir dar na praia 8 ἐκπ. εἰς ἀλλότριον ἦθος plat. degenerar em costume estranho, ἐκπ. ἐς ἀλλότριον εἶδος plat. mudar em outra forma (de governo) 9 ἐκπ. ἐξ οἰκίας xen. sair precipitadamente da casa, ἐκπ. τῆς ἀγορᾶς plut. sair precipitadamente da praça 10 ἐκ δ᾽ αὐτοῦ φωνὴν ἐξέπεσε plut. dele (bosque) saiu uma voz, ἐκ τοῦ σταυρώματος ἐξέπιπτον xen. lançaram-se para fora da paliçada, ἐκπ. Ἀθήναζε tuc. fugir para Atenas 11 ψευδεῖς εἰσιν οἱ νῦν ἐκπίπτοντες ἐκεῖ χρησμοί; luc. são falsos os oráculos agora tornados públicos aí?</p></section></article>\n<article id=\"entry-dgp-12662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπίτνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1423 na letra ε · nº geral 12662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres.) = ἐκπίπτω.</p></section></article>\n<article id=\"entry-dgp-12663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπλεος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1424 na letra ε · nº geral 12663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἔκπλεως.</p></section></article>\n<article id=\"entry-dgp-12664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπλέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1425 na letra ε · nº geral 12664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐξεπλεύσομαι, aor. ἐξέπλευσα) 1 levantar âncora; sair do porto; partir em viagem por mar de um lugar, gen. ou ἐκ e gen., em direção a, εἰς e ac., contra alguém, ἐπί e ac., para algo, κατά e ac.: ἐκπ. τὸν ὕστερον ἔκπλουν dem. embarcar para a nova travessia 2 (peixe) navegar em direção a; emigrar para, εἰς e ac. 3 ultrapassar um lugar, ac, navegando 4 sair de, ἐκ e gen.: ἐκπ. ἐκ τοῦ νόου ou ἐκ τῶν φρενῶν her. perder a razão, o juízo.</p></section></article>\n<article id=\"entry-dgp-12665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπλεως, ως, ων</h1><div class=\"entry-meta\"><span>DGP · ordem 1426 na letra ε · nº geral 12665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de; satisfeito de, gen. 2 completo 3 abundante.</p></section></article>\n<article id=\"entry-dgp-12666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπληγεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1427 na letra ε · nº geral 12666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor.2 pas. ép. de ἐκπλήσσω.</p></section></article>\n<article id=\"entry-dgp-12667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπλήγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1428 na letra ε · nº geral 12667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só inf. pres. pas. ἐκπλήγνυσθαι) = ἐκ­πλήσσω.</p></section></article>\n<article id=\"entry-dgp-12668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπληκτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1429 na letra ε · nº geral 12668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 próprio para maravilhar, para espantar 2 espantoso; surpreendente; terrível. 〈ἐκπλήσσω〉</p></section></article>\n<article id=\"entry-dgp-12669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπληκτικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1430 na letra ε · nº geral 12669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de modo espantoso; de maneira surpreendente 2 de maneira terrível.</p></section></article>\n<article id=\"entry-dgp-12670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπληκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1431 na letra ε · nº geral 12670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 terrificante; assombroso 2 atônito; estupefato. 〈ἐκπλήσσω〉</p></section></article>\n<article id=\"entry-dgp-12671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπλήκτως</h1><div class=\"entry-meta\"><span>DGP · ordem 1432 na letra ε · nº geral 12671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 terrivelmente 2 com terror; com medo; com estupor.</p></section></article>\n<article id=\"entry-dgp-12672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπληξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1433 na letra ε · nº geral 12672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estupor; medo; terror: ἔκπ. ἐκ κακῶν ésql. terror causado pelos infortúnios, ἔκπληξιν παρέχειν ant. suscitar o terror, ἔκπ. ἐμποιεῖν τινι tuc. inspirar terror em alguém, ἐς ἔκπληξιν καθιστάναι tuc. apavorar 2 perturbação mental; paixão. 〈ἐκπλήσσω〉</p></section></article>\n<article id=\"entry-dgp-12673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπληρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1434 na letra ε · nº geral 12673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encher inteiramente 2 completar 3 acrescentar para completar; completar elevando: δέκατον ὄχον ἐκπληρῶν sóf. completando o número de dez carros 4 equipar por completo: ἐκπ. τριήρεις equipar trirremes 5 satisfazer; cumprir: ἐκπ. τὴν ὑπόσχεσιν her. cumprir a promessa, ἐκπ. τὸ χρέος plat. pagar a dívida 6 percorrer por inteiro: ἐκπ. λιμένα πλάτῃ eur. percorrer o porto a remo ♦ pas. 7 tornar-se completo; ser cumprido: ὑμῖν ἡ χάρις ἐκπεπλήρωται her. o favor foi levado até o fim por vós.</p></section></article>\n<article id=\"entry-dgp-12674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπλήσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1435 na letra ε · nº geral 12674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ήττω (fut. ἐκπλήξω, aor. ἐξέπληξα; pas. fut. ἐκπλαγήσομαι, aor.2 ἐξεπλήγην e ἐξεπλάγην, perf. ἐκπέπληγμαι) 1 abater; derrubar alguém, ac., de, gen.: αὐτὸν ἐξέπληξε τῶν ὑψηγόρων κομπασμάτων ésql. derrubou-o de suas jactâncias insolentes 2 atordoar; perturbar; pasmar; espantar: ἡ τέρψις τὸ λυπηρὸν ἐκπλήττει tuc. o gozo espanta a dor, φόβος μνήμην ἐκπλήττει tuc. o medo perturba a memória 3 desviar alguém, ac., pela força ou pelo medo, de, gen.: ἐκπ. ὁδοῦ eur. desviar de seu caminho, ὁ μ᾽ ἐκπλήσσει λόγου eur. o que me tolhe a palavra 4 impedir de, gen. ou inf.: ἐκπ. λέγειν eur. impedir de falar ♦ pas. 5 estar surpreso, perturbado ou aterrorizado diante da visão ou da idéia de algo, dat., ac., ἐπί e dat., διά ou πρός e ac., ὑπό e gen.; estar chocado com alguém, ac.: μή με ἐκπλαγῆτ᾽ ἀπηγριωμένον sóf. não vos choqueis comigo assim asselvajado, ἡμᾶς δ᾽ ἂν μάλιστα ἐκπεπληγμένοι εἶεν tuc. em relação a nós mais ficariam assustados.</p></section></article>\n<article id=\"entry-dgp-12675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπλήσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1436 na letra ε · nº geral 12675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de ἐκπίμπλημι.</p></section></article>\n<article id=\"entry-dgp-12676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπλοος-ους, όου-ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1437 na letra ε · nº geral 12676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 partida; embarque; saída de barco 2 porto. 〈ἐκπλέω〉</p></section></article>\n<article id=\"entry-dgp-12677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπλύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1438 na letra ε · nº geral 12677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lavar; eliminar por meio de lavagem 2 lavar completamente; limpar ♦ méd. 3 tirar lavando; lavar-se ♦ pas. 4 desaparecer com lavagem.</p></section></article>\n<article id=\"entry-dgp-12678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκπλυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1439 na letra ε · nº geral 12678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lavado; limpo 2 que desbota. 〈ἐκπλύνω〉</p></section></article>\n<article id=\"entry-dgp-12679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπλώω</h1><div class=\"entry-meta\"><span>DGP · ordem 1440 na letra ε · nº geral 12679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐκπλέω.</p></section></article>\n<article id=\"entry-dgp-12680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπνείω</h1><div class=\"entry-meta\"><span>DGP · ordem 1441 na letra ε · nº geral 12680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐκπνέω.</p></section></article>\n<article id=\"entry-dgp-12681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπνευματόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1442 na letra ε · nº geral 12681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer evaporar 2 expulsar o ar; fazer murchar ♦ pas. 3 transformar-se em vapor 4 ser inflado. 〈ἐκ, πνεῦμα〉</p></section></article>\n<article id=\"entry-dgp-12682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπνέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1443 na letra ε · nº geral 12682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 expirar; soprar 2 exalar: ἐκπ. ψυχήν ou βίον exalar a vida, expirar, morrer 3 expirar; morrer pelas mãos de alguém, ὑπό ou πρός e gen. 4 (vento) soprar de um lugar, ἐκ e gen.: ἐκπ. ἐκ τοῦ κόλπου tuc. soprar do golfo, μικροῦ νέφους τις ἐκπνεύσας μέγας χείμων sóf. uma grande tempestade que sopra de uma pequena nuvem, ἐκπ. ἔσωθεν her. soprar de dentro 5 cessar de soprar; tornar-se calmo 6 (povo) perder a força.</p></section></article>\n<article id=\"entry-dgp-12683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπνοή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1444 na letra ε · nº geral 12683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 expiração; exalação 2 ação de expirar; morte 3 vento; sopro 4 vapor. 〈ἐκπνέω〉</p></section></article>\n<article id=\"entry-dgp-12684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκποδών</h1><div class=\"entry-meta\"><span>DGP · ordem 1445 na letra ε · nº geral 12684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 longe; ao longe (lit. fora do alcance dos pés): ἐκπ. ἀπαλλάσσεσθαι her. deixar um país e ir-se embora, ἐκπ. ἔχειν ἑαυτόν ésql. manter-se afastado, ἐκπ. εἶναι xen. estar afastado de algo, gen., ἐκπ. στῆναι tuc. ficar ou estar afastado de alguém, dat., ἐκπ. γίγνεσθαι xen. desaparecer, morrer, ἐκπ. ἄγειν afastar alguém ou algo, ac., ἐκπ. ποιεῖσθαι xen. livrar-se de alguém ou de algo, ac. ♦ prep. 2 longe de, gen.: ἐκπ. χθονός sóf. longe do país, τούτων ἐκποδὼν ἦμεν xen. estávamos longe deles. 〈ἐκ, πούς〉</p></section></article>\n<article id=\"entry-dgp-12685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκποιέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1446 na letra ε · nº geral 12685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar completo; findar; terminar; construir; munir: τὰς ὁδοὺς γεφύραις ἐκπ. d.c. munir de calçadas os caminhos, Παρίου λίθου τὰ ἔμπροσθε αὐτοῦ ἐξεποίησαν her. construíram a fachada dele [do templo] com mármore de Paros 2 acarretar; causar; permitir; impes. é permitido, inf. 3 dar em adoção (filho) 4 subtrair: ἐκπ. ἑαυτὸν τοῦ δικαστηρίου filós. subtrair-se a um processo ♦ méd. 5 produzir; engendrar.</p></section></article>\n<article id=\"entry-dgp-12686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκποίησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1447 na letra ε · nº geral 12686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 emissão de esperma 2 cessão (de criança) para adoção 3 execução; acabamento de uma obra. 〈ἐκποιέω〉</p></section></article>\n<article id=\"entry-dgp-12687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκποίητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1448 na letra ε · nº geral 12687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dado em adoção 2 libertado de, gen.</p></section></article>\n<article id=\"entry-dgp-12688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπολεμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1449 na letra ε · nº geral 12688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 incitar alguém, ac., à guerra contra, πρός e ac. 2 levar a guerra 3 entrar em guerra contra, ac.</p></section></article>\n<article id=\"entry-dgp-12689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπολεμόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1450 na letra ε · nº geral 12689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 incitar alguém, ac., à guerra contra alguém, dat. ou πρός e ac.; levar à guerra; tornar hostil, inimigo ♦ méd. 2 tornar-se inimigo de; entrar em guerra contra, dat.</p></section></article>\n<article id=\"entry-dgp-12690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκπολέμωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1451 na letra ε · nº geral 12690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">incitação à guerra; hostilidade. 〈ἐκπολεμόω〉</p></section></article>\n";
